parameters.jsCode:
const allItems = $input.all();
let followers = [];

if (allItems.length > 1) {
  // Phantombuster returned one item per follower — collect them all
  followers = allItems.map(item => item.json);
} else {
  // Single item — try to extract followers from structured fields
  const agentOutput = allItems[0].json;

  // Path 1: top-level resultObject as JSON string
  if (!followers.length && agentOutput.resultObject) {
    try {
      const parsed = JSON.parse(agentOutput.resultObject);
      if (Array.isArray(parsed)) followers = parsed;
    } catch(e) {}
  }

  // Path 2: nested data.resultObject
  if (!followers.length && agentOutput.data?.resultObject) {
    try {
      const raw = agentOutput.data.resultObject;
      const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
      if (Array.isArray(parsed)) followers = parsed;
    } catch(e) {}
  }

  // Path 3: top-level result array
  if (!followers.length && Array.isArray(agentOutput.result)) {
    followers = agentOutput.result;
  }

  // Path 4: data.result
  if (!followers.length && Array.isArray(agentOutput.data?.result)) {
    followers = agentOutput.data.result;
  }

  // Debug fallback
  if (!followers.length) {
    return [{ json: { followers: [], _debug_keys: Object.keys(agentOutput), _debug_sample: agentOutput } }];
  }
}

return [{ json: { followers } }];

const masterItems = $input.all();

// Normalise: lowercase + strip trailing slash
const normalise = url => (url || '').trim().toLowerCase().replace(/\/+$/, '');

const masterUrls = new Set(
  masterItems.map(item => normalise(item.json.profileUrl)).filter(Boolean)
);

const phantomData = $('Parse Phantom Output').first().json.followers;
const newFollowers = phantomData.filter(f => !masterUrls.has(normalise(f.profileLink)));

// Surface counts as first item for easy verification, then the actual new followers
console.log(`Master URLs loaded: ${masterUrls.size}`);
console.log(`Phantom followers: ${phantomData.length}`);
console.log(`New followers found: ${newFollowers.length}`);
console.log('masterUrls size:', masterUrls.size);
console.log('first 3 master URLs:', [...masterUrls].slice(0,3));
console.log('first 3 phantom profileLinks:', phantomData.slice(0,3).map(f => f.profileLink));
console.log('first phantom match test:', masterUrls.has(normalise(phantomData[0]?.profileLink)));

return newFollowers.map(f => ({ json: f }));

const HEADERS = [
  'classification', 'scrapeRound',
'fullName', 'firstName_from_input', 'lastName_from_input', 'profileUrl', 'followers', 'isFollowing', 'timestamp of download', 'companyIndustry', 'companyName', 'companyWebsite', 'linkedinCompanyUrl', 'linkedinCompanySlug', 'linkedinCompanyId', 'linkedinDescription', 'linkedinHeadline', 'linkedinIsHiringBadge', 'linkedinIsOpenToWorkBadge', 'linkedinJobDateRange', 'linkedinJobLocation', 'linkedinPreviousJobDescription', 'linkedinJobTitle', 'linkedinProfileId', 'linkedinProfileSlug', 'linkedinProfileUrl', 'linkedinProfileUrn', 'linkedinProfileImageUrl', 'linkedinSkillsLabel', 'location', 'mutualConnectionsUrl', 'connectionsUrl', 'linkedinCompanyName', 'linkedinCompanyDescription','linkedinCompanyTagline', 'linkedinCompanyFollowerCount', 'linkedinCompanyWebsite', 'linkedinCompanyEmployeesCount', 'linkedinCompanySize', 'linkedinCompanyIndustry', 'linkedinCompanyHeadquarter', 'linkedinCompanySpecialities', 'linkedinCompanyFounded'
];

const item = {};
for (const h of HEADERS) item[h] = '';
return [{ json: item }];

const masterItems = $input.all();
const normalise = url => (url || '').trim().toLowerCase().replace(/\/+$/, '');

const phantomFollowers = $('Parse Phantom Output').first().json.followers;
const phantomUrls = new Set(
  phantomFollowers.map(f => normalise(f.profileLink)).filter(Boolean)
);

// Header is NOT in Read Master output. masterItems[0] = row 2, so rowNumber = index + 2.
const lostRows = masterItems
  .map((item, index) => ({
    profileLink: item.json.profileUrl,
    rowNumber: index + 2
  }))
  .filter(row => {
    const url = normalise(row.profileLink);
    return url && !phantomUrls.has(url);
  })
  .sort((a, b) => b.rowNumber - a.rowNumber);

console.log(`Master rows: ${masterItems.length}`);
console.log(`Phantom URLs: ${phantomUrls.size}`);
console.log(`Lost followers: ${lostRows.length}`);

return [{
  json: {
    lostCount: lostRows.length,
    lostFollowers: lostRows.map(r => r.profileLink),
    lostRowNumbers: lostRows.map(r => r.rowNumber)
  }
}];

const { lostRowNumbers } = $input.first().json;
if (!lostRowNumbers || lostRowNumbers.length === 0) return [];
// Extra guard: only valid integers > 1 (row 1 is the header — never delete it)
const valid = lostRowNumbers.filter(n => Number.isInteger(n) && n > 1);
if (valid.length === 0) return [];
// Already sorted descending — safe bottom-up deletion
return valid.map(rowNumber => ({ json: { rowNumber } }));

