const allItems = $input.all();

// Append New Followers returns sheet column names (profileUrl, not profileLink)
const followerItems = allItems.filter(item => item.json.profileUrl !== undefined);
const newCount = followerItems.length;

// lostCount lives in Find Lost Followers — not passed through Delete from Master
const lostCount = $('Find Lost Followers').first().json.lostCount ?? 0;

return [{
  json: {
    newCount,
    lostCount,
    newFollowers: followerItems.map(item => item.json)
  }
}];

const enrichmentItems = $input.all();
const newFollowers = $('Aggregate').first().json.newFollowers;

const normalise = url => (url || '').trim().replace(/\/+$/, '');

return enrichmentItems.map((item, index) => {
  const follower = newFollowers[index];
  // profileLink is the Phantom follower field; profileUrl is a fallback
  const profileUrl = normalise(follower?.profileLink ?? follower?.profileUrl ?? '');
  return {
    json: {
      ...item.json,
      profileUrl, // after spread: overrides any trailing-slash profileUrl from the scraper
    }
  };
});

const item = $input.first();
const text = item.json.output?.[0]?.content?.[0]?.text ?? {};
const classification = typeof text === 'string'
  ? String(Object.values(JSON.parse(text))[0] ?? '')
  : String(Object.values(text)[0] ?? '');
return [{ json: { classification } }];

// Build the follower-change summary for the email report.
// Per-label counts are DYNAMIC: whatever labels your classifier produced are
// counted automatically -- no category name is hardcoded here.
const masterFinalItems = $input.all();
const masterFinalCount = masterFinalItems.length;

const newFollowers = $('Get row(s) in sheet').all().map(i => i.json);
const lostFollowers = $('Expand Lost Rows').all();

const new_total = newFollowers.length;
const lost_total = lostFollowers.length;

// Count every distinct classification label across the whole master sheet.
const label_counts = {};
for (const it of masterFinalItems) {
  const label = String(it.json.classification ?? '').trim();
  if (!label) continue;
  label_counts[label] = (label_counts[label] || 0) + 1;
}

return [{
  json: {
    new_connections_total: masterFinalCount,
    net_increase_total: new_total - lost_total,
    lost_connections: lost_total,
    label_counts,
  }
}];
